refentry.refsect1:
&reftitle.description;

 boolldap_bind
 LDAP\Connectionldap
 stringnulldn&null;
 #[\SensitiveParameter]stringnullpassword&null;


 指定した RDN およびパスワードを用いて LDAP ディレクトリにバインドします。



  ldap_connect は接続パラメータを初期化するだけで、
  LDAP サーバーへの実際のネットワーク接続は、この関数が確立します。
  LDAP_OPT_PROTOCOL_VERSION や TLS 関連のオプションなど、
  接続に影響するオプションは、この関数をコールする前に設定しなければなりません。

&reftitle.parameters;
ldap
&ldap.parameter.ldap;
dn
password
password を省略または空にした場合は匿名バインドを試みます。 匿名バインドのため、dn も空のままにできます。 これは、https://tools.ietf.org/html/rfc2251#section-4.2.2 で定義されています。

  &reftitle.examples;



    LDAP バインドの使用


<?php

// ldap バインドを使用する
$ldaprdn  = 'uname';     // ldap rdn あるいは dn
$ldappass = 'password';  // パスワード

// ldap サーバーに接続する
$ldapconn = ldap_connect("ldap://ldap.example.com")
    or die("Could not connect to LDAP server.");

if ($ldapconn) {

    // ldap サーバーにバインドする
    $ldapbind = ldap_bind($ldapconn, $ldaprdn, $ldappass);

    // バインド結果を検証する
    if ($ldapbind) {
        echo "LDAP bind successful...";
    } else {
        echo "LDAP bind failed...";
    }

}

?>




    LDAP 匿名バインドの使用


<?php

// ldap 匿名バインドを使用する

// ldap サーバーに接続する
$ldapconn = ldap_connect("ldap://ldap.example.com")
    or die("Could not connect to LDAP server.");

if ($ldapconn) {

    // 匿名でバインドする
    $ldapbind = ldap_bind($ldapconn);

    if ($ldapbind) {
        echo "LDAP bind anonymous successful...";
    } else {
        echo "LDAP bind anonymous failed...";
    }

}

?>
